   306	                            openContextMenu: () => setShouldKeepOpen(true),
   307	                            interceptAnonymousUser,
   308	                            openOverflowMenu,
   309	                            setIsEmojiPickerActive,
   310	                            moneyRequestAction,
   311	                        };
   312	
   313	                        if ('renderContent' in contextAction) {
   314	                            return contextAction.renderContent(closePopup, payload);
   315	                        }
   316	
   317	                        const {textTranslateKey} = contextAction;
