   319	                            textTranslateKey === 'reportActionContextMenu.editAction' ||
   320	                            textTranslateKey === 'reportActionContextMenu.deleteAction' ||
   321	                            textTranslateKey === 'reportActionContextMenu.deleteConfirmation';
